def read_raw_dataframe():
    # Training-only path; used the very first time the app runs on a machine
    # with no ./assets folder yet. Retraining expects the raw DataCo CSV in
    # the project folder - no embedded data.
    for name in ("DataCoSupplyChainDataset.csv", "data.csv"):
        path = BASE_DIR / name
        if not path.exists():
            continue
        df = pd.read_csv(path, encoding="latin-1")

        # The raw CSV has no "Order Month" / "Order Weekday" columns - both
        # are derived here from "order date (DateOrders)" (order-time info,
        # so this is leakage-free). Missing/unparseable dates fall back to
        # the training-set typical month/weekday (June / Thursday) rather
        # than silently zeroing every row.
        if "Order Month" not in df.columns or "Order Weekday" not in df.columns:
            date_col = "order date (DateOrders)"
            if date_col in df.columns:
                order_dt = pd.to_datetime(df[date_col], errors="coerce")
            else:
                order_dt = pd.Series(pd.NaT, index=df.index)
            if "Order Month" not in df.columns:
                df["Order Month"] = order_dt.dt.month.fillna(6).astype(int)
            if "Order Weekday" not in df.columns:
                df["Order Weekday"] = order_dt.dt.dayofweek.fillna(3).astype(int)

        for col in CATEGORICAL_COLS:
            if col in df.columns:
                df[col] = df[col].astype(str)
        for col in NUMERIC_COLS:
            if col in df.columns:
                df[col] = pd.to_numeric(df[col], errors="coerce")
        df.dropna(subset=[TARGET], inplace=True)
        df.fillna(0, inplace=True)
        df[TARGET] = df[TARGET].astype(int)
        print("Raw dataset loaded: %s (%d rows)" % (path.name, len(df)))
        return df
    raise RuntimeError(
        "Raw dataset CSV not found next to this script. On a machine with no "
        "./assets folder yet, SupplyShield AI trains itself once from the raw "
        "DataCo CSV - place 'DataCoSupplyChainDataset.csv' (or 'data.csv') in "
        "the same folder as this .py file and run it again.")


def select_columns(df):
    numeric_cols = [c for c in NUMERIC_COLS if c in df.columns]
    cats = [c for c in CATEGORICAL_COLS if c in df.columns]
    cats = [c for c in cats if df[c].nunique() > 1]            # drop constants
    te_cols = [c for c in cats
               if (c in TE_RISK_NAME) or (df[c].nunique() > CARDINALITY_LIMIT)]
    label_cols = [c for c in cats if c not in te_cols]
    return numeric_cols, label_cols, te_cols


