# ─────────────────────────────────────────────────────────────────────────────


def engineer_dataframe(df):
    wd   = df["Order Weekday"].astype(float)  if "Order Weekday"            in df else 0.0
    mo   = df["Order Month"].astype(float)    if "Order Month"              in df else 6.0
    qty  = df["Order Item Quantity"].astype(float) if "Order Item Quantity" in df else 0.0
    disc = df["Order Item Discount"].astype(float) if "Order Item Discount" in df else 0.0
    drt  = df["Order Item Discount Rate"].astype(float) if "Order Item Discount Rate" in df else 0.0
    prc  = df["Order Item Product Price"].astype(float) if "Order Item Product Price" in df else 0.0
    sch  = df["Days for shipment (scheduled)"].astype(float) if "Days for shipment (scheduled)" in df else 0.0
    sales= df["Sales"].astype(float) if "Sales" in df else 0.0
    ship = df["Shipping Mode"].astype(str) if "Shipping Mode" in df else "0"
    return pd.DataFrame({
        "Order Quarter":           ((mo - 1) // 3) % 4 + 1,
        "Is Weekend Order":        ((wd % 7).isin([5, 6])).astype(float),
        "Order Value":             prc * qty,
        "Discount Times Quantity": disc * qty,
        "High Discount Flag":      (drt >= 0.18).astype(float),
        "Express Shipping Flag":   (ship.str.lower().isin(["3", "same day", "same-day", "express"])).astype(float),
        "Shipping Urgency":        np.minimum(1.0, sch / 4.0),
        "Month Sine":              np.sin(2 * np.pi * mo / 12.0),
        "Month Cosine":            np.cos(2 * np.pi * mo / 12.0),
        "Weekday Sine":            np.sin(2 * np.pi * wd / 7.0),
        "Weekday Cosine":          np.cos(2 * np.pi * wd / 7.0),
        "Peak Season Flag":        mo.isin([11, 12]).astype(float),
        "Bulk Order Flag":         (qty >= 4).astype(float),
        "Sales Per Unit":          sales / qty.clip(lower=1e-9),
    })


def engineer_from_dict(n):
    wd   = float(n.get("Order Weekday", 3.0))
    mo   = float(n.get("Order Month", 6.0))
    qty  = float(n.get("Order Item Quantity", 0.0))
    disc = float(n.get("Order Item Discount", 0.0))
    drt  = float(n.get("Order Item Discount Rate", 0.0))
    prc  = float(n.get("Order Item Product Price", 0.0))
    sch  = float(n.get("Days for shipment (scheduled)", 4.0))
    sales= float(n.get("Sales", 0.0))
    ship = str(n.get("Shipping Mode", "0")).lower()
    exp  = 1.0 if ship in ("3", "same day", "same-day", "express") else 0.0
    return {
        "Order Quarter":           float(((mo - 1) // 3) % 4 + 1),
        "Is Weekend Order":        float(1 if (wd % 7) in (5., 6.) else 0),
        "Order Value":             prc * qty,
        "Discount Times Quantity": disc * qty,
        "High Discount Flag":      float(1 if drt >= 0.18 else 0),
        "Express Shipping Flag":   exp,
        "Shipping Urgency":        float(min(1.0, sch / 4.0)),
        "Month Sine":              float(np.sin(2 * np.pi * mo / 12.0)),
        "Month Cosine":            float(np.cos(2 * np.pi * mo / 12.0)),
        "Weekday Sine":            float(np.sin(2 * np.pi * wd / 7.0)),
        "Weekday Cosine":          float(np.cos(2 * np.pi * wd / 7.0)),
        "Peak Season Flag":        float(1 if mo in (11., 12.) else 0),
        "Bulk Order Flag":         float(1 if qty >= 4 else 0),
        "Sales Per Unit":          float(sales / max(qty, 1e-9)),
    }


def te_encoding(series, y, smoothing=TE_SMOOTHING):
    s = np.asarray(series)
    d = np.asarray(y, dtype=float)
    g = pd.DataFrame({"k": s, "y": d}).groupby("k")["y"].agg(["mean", "count"])
    gmean = float(d.mean())
    enc = ((g["mean"] * g["count"]) + (smoothing * gmean)) / (g["count"] + smoothing)
    return enc.to_dict(), gmean


def label_codes(series, le):
    inv = {cls: i for i, cls in enumerate(le.classes_)}
    return np.array([inv.get(v, 0) for v in series], dtype=np.float64)


def te_codes(series, m, gmean):
    return np.array([m.get(v, gmean) for v in series], dtype=np.float64)


def assemble(num_df, eng_df, lab, te, numeric_cols, label_cols, te_cols, freq=None):
    parts, names = [], []
    for c in numeric_cols:
        parts.append(num_df[c].astype(float).values)
        names.append(c)
    for c in ENGINEERED_COLS:
        parts.append(eng_df[c].astype(float).values)
        names.append(c)
    for c in label_cols:
        parts.append(lab[c])
        names.append(c)
    for c in te_cols:
        parts.append(te[c])
        names.append(TE_RISK_NAME.get(c, c))
    if freq is not None:
        for c in te_cols:
            parts.append(freq[c])
            names.append("Freq " + TE_RISK_NAME.get(c, c))
    return np.column_stack(parts).astype(np.float64), names


def apply_interactions(df, te_cols):
    for a, b in TE_INTERACT:
        if a in df.columns and b in df.columns:
            key = a + "__" + b
            df[key] = df[a].astype(str) + "|" + df[b].astype(str)
            if key not in te_cols:
                te_cols.append(key)
            if key not in TE_RISK_NAME:
                TE_RISK_NAME[key] = a + " x " + b
    return te_cols


def load_and_preprocess():
    """Leakage-free feature build.

    Target-encoding maps are learned ONLY from the training split and applied
    consistently to training, hold-out, test and live inference rows (smoothing
    shrinks the in-sample self-influence toward the training prior). No target /
    outcome information is ever read from test rows.
    """
    df = read_raw_dataframe()
    numeric_cols, label_cols, te_cols = select_columns(df)
    te_cols = apply_interactions(df, te_cols)
    cat_cols = label_cols + te_cols
    eng_df = engineer_dataframe(df).reset_index(drop=True)
    y = df[TARGET].values

    idx = np.arange(len(y))
    idx_tr, idx_te = train_test_split(idx, test_size=0.2, stratify=y, random_state=42)

    defaults_num = {c: float(df.iloc[idx_tr][c].median()) for c in numeric_cols}
    defaults_cat = {c: str(df.iloc[idx_tr][c].value_counts().idxmax()) for c in label_cols}

    train_df = df.iloc[idx_tr].reset_index(drop=True)
    test_df  = df.iloc[idx_te].reset_index(drop=True)
    eng_tr   = eng_df.iloc[idx_tr].reset_index(drop=True)
    eng_te   = eng_df.iloc[idx_te].reset_index(drop=True)
    y_train, y_test = y[idx_tr], y[idx_te]

    le_map = {c: LabelEncoder().fit(train_df[c].values) for c in label_cols}

    gmean = float(y_train.mean())
    te_map = {}
    for c in te_cols:
        m, _ = te_encoding(train_df[c].values, y_train)
        te_map[c] = m

    lab_tr = {c: label_codes(train_df[c].values, le_map[c]) for c in label_cols}
    lab_te = {c: label_codes(test_df[c].values, le_map[c]) for c in label_cols}
    te_tr  = {c: te_codes(train_df[c].values, te_map[c], gmean) for c in te_cols}
    te_te  = {c: te_codes(test_df[c].values, te_map[c], gmean) for c in te_cols}

    full_df = df.reset_index(drop=True)
    freq_maps = {}
    fr_tr, fr_te, fr_all = {}, {}, {}
    for c in te_cols:
        cnt = train_df[c].value_counts().to_dict()
        freq_maps[c] = cnt
        fr_tr[c]  = np.log1p(np.array([cnt.get(v, 0) for v in train_df[c].values]))
        fr_te[c]  = np.log1p(np.array([cnt.get(v, 0) for v in test_df[c].values]))
        fr_all[c] = np.log1p(np.array([cnt.get(v, 0) for v in full_df[c].values]))

    X_train, final_cols = assemble(train_df, eng_tr, lab_tr, te_tr,
                                   numeric_cols, label_cols, te_cols, freq=fr_tr)
    X_test, _ = assemble(test_df, eng_te, lab_te, te_te,
                         numeric_cols, label_cols, te_cols, freq=fr_te)

    lab_all = {c: label_codes(df[c].values, le_map[c]) for c in label_cols}
    te_all  = {c: te_codes(df[c].values, te_map[c], gmean) for c in te_cols}
    X_all, _ = assemble(full_df, eng_df, lab_all, te_all,
                        numeric_cols, label_cols, te_cols, freq=fr_all)

    return {
        "X_train": X_train, "y_train": y_train,
        "X_test":  X_test,  "y_test":  y_test,
        "X_all": np.asarray(X_all, dtype=np.float64), "y_all": y,
        "final_cols": final_cols,
        "le_map": le_map, "te_map": te_map, "gmean": gmean,
        "numeric_cols": numeric_cols, "label_cols": label_cols, "te_cols": te_cols,
        "freq_maps": freq_maps,
        "defaults_num": defaults_num, "defaults_cat": defaults_cat,
        "te_interact": list(TE_INTERACT),
    }


