def load_model():
    frozen_path = ASSETS_DIR / "supplyshield_frozen.pkl"
    if not frozen_path.exists():
        print("Missing production asset: assets/supplyshield_frozen.pkl")
        sys.exit(1)
    print("Loading frozen model...")
    with open(frozen_path, "rb") as f:
        a = pickle.load(f)
    STATE["models"]       = {"XGBoost": a["model"]}
    STATE["results"]      = a["results"]
    STATE["feat_imp"]     = a["feat_imp"]
    STATE["risk_dist"]    = a["risk_dist"]
    STATE["le_map"]       = a["le_map"]
    STATE["te_map"]       = a["te_map"]
    STATE["gmean"]        = a["gmean"]
    STATE["numeric_cols"] = a["numeric_cols"]
    STATE["label_cols"]   = a["label_cols"]
    STATE["te_cols"]      = a["te_cols"]
    STATE["te_interact"]  = a["te_interact"]
    STATE["freq_maps"]    = a["freq_maps"]
    STATE["defaults_num"] = a["defaults_num"]
    STATE["defaults_cat"] = a["defaults_cat"]
    STATE["model"]        = a["model"]
    STATE["calibrator"]   = a["calibrator"]
    STATE["threshold"]    = a["threshold"]
    STATE["y"]            = a["y_all"]
    print("Model: XGBoost | boosting rounds=%d | features=%d | operating threshold=%.2f" % (
        STATE["model"].get_booster().num_boosted_rounds(),
        int(STATE["model"].n_features_in_), STATE.get("threshold") or 0))


def save_model(bundle):
    ASSETS_DIR.mkdir(parents=True, exist_ok=True)
    with open(ASSETS_DIR / "supplyshield_frozen.pkl", "wb") as f:
        pickle.dump(bundle, f, protocol=pickle.HIGHEST_PROTOCOL)
    print("Frozen model saved: assets/supplyshield_frozen.pkl")


def save_processed(p):
    # Companion asset to the frozen model: the full processed feature matrix,
    # used at run time as the pool of reference orders (see verify_encoders /
    # score_order). Built once, on the very first run, from the raw CSV.
    ASSETS_DIR.mkdir(parents=True, exist_ok=True)
    bundle = {
        "X_all":     np.asarray(p["X_all"], dtype=np.float64),
        "y_all":     np.asarray(p["y_all"]),
        "feat_cols": list(p["final_cols"]),
    }
    with open(ASSETS_DIR / "processed_data.pkl", "wb") as f:
        pickle.dump(bundle, f, protocol=pickle.HIGHEST_PROTOCOL)
    print("Processed dataset saved: assets/processed_data.pkl")


def load_processed():
    data_path = ASSETS_DIR / "processed_data.pkl"
    if not data_path.exists():
        print("Missing production asset: assets/processed_data.pkl")
        sys.exit(1)
    with open(data_path, "rb") as f:
        d = pickle.load(f)
    STATE["X"]         = d["X_all"]
    STATE["y"]         = d["y_all"]
    STATE["feat_cols"] = list(d["feat_cols"])
    STATE["ci"]        = {n: i for i, n in enumerate(STATE["feat_cols"])}
    print("%d features loaded." % len(STATE["feat_cols"]))
    print("Processed assets loaded.")


def verify_encoders():
    """Fail fast if the encoder tables above do not match the frozen assets.

    Every check compares the tables with the processed dataset, so a wrong or
    outdated mapping stops the server instead of silently scoring the wrong
    category.
    """
    X, y, ci = STATE["X"], STATE["y"], STATE["ci"]
    problems = []

    if len(STATE["feat_cols"]) != int(STATE["model"].n_features_in_):
        problems.append("feature count %d != model input %d"
                        % (len(STATE["feat_cols"]), STATE["model"].n_features_in_))

    def label_col(field, table):
        classes = [str(c) for c in STATE["le_map"][field].classes_]
        col = X[:, ci[field]].astype(int)
        for name, entry in table.items():
            code, rows = entry[0], entry[-1]
            if code not in classes:
                problems.append("%s: code %s missing from encoder" % (name, code))
                continue
            n = int((col == classes.index(code)).sum())
            if n != rows:
                problems.append("%s %r (code %s): %d rows, expected %d" % (field, name, code, n, rows))
        return col, classes

    ship_col, ship_classes = label_col("Shipping Mode", SHIPPING_MODES)
    label_col("Market", MARKETS)
    label_col("Customer Segment", SEGMENTS)

    # each shipping code has exactly one scheduled lead time in the data
    days = X[:, ci["Days for shipment (scheduled)"]]
    flag = X[:, ci["Express Shipping Flag"]]
    for name, (code, lead, _rows) in SHIPPING_MODES.items():
        m = ship_col == ship_classes.index(code)
        if not (np.all(days[m] == lead)):
            problems.append("%s: scheduled days are not always %d" % (name, lead))
        if not np.all(flag[m] == (1.0 if code == "3" else 0.0)):
            problems.append("%s: 'Express Shipping Flag' does not follow code 3" % name)

    # Department Id <-> code: row counts + stored target/frequency encodings
    did = X[:, ci["Department Id"]].astype(int)
    te_col = X[:, ci["Department Risk Frequency"]]
    fq_col = X[:, ci["Freq Department Risk Frequency"]]
    for name, (dep_id, code, rows) in DEPARTMENTS.items():
        m = did == dep_id
        if int(m.sum()) != rows:
            problems.append("Department %r (Id %d): %d rows, expected %d" % (name, dep_id, int(m.sum()), rows))
            continue
        if not np.allclose(te_col[m], STATE["te_map"]["Department Name"].get(code, -1), atol=1e-9):
            problems.append("Department %r: code %s does not match its target encoding" % (name, code))
        if not np.allclose(fq_col[m], np.log1p(STATE["freq_maps"]["Department Name"].get(code, 0)), atol=1e-9):
            problems.append("Department %r: code %s does not match its frequency encoding" % (name, code))

    if problems:
        print("Encoder verification FAILED:")
        for p in problems:
            print("  - " + p)
        sys.exit(1)
    print("Encoders verified against processed data (shipping mode, market, segment, department).")

    # Training-domain limits for the numeric form inputs (used to flag out-of-range values).
    STATE["ranges"] = {
        "days":     (float(days.min()), float(days.max())),
        "quantity": (float(X[:, ci["Order Item Quantity"]].min()), float(X[:, ci["Order Item Quantity"]].max())),
        "discount": (float(X[:, ci["Order Item Discount Rate"]].min()), float(X[:, ci["Order Item Discount Rate"]].max())),
    }

    # Fixed reference sample of real orders (deterministic).
    rng = np.random.RandomState(REFERENCE_SEED)
    idx = rng.choice(len(X), size=min(N_REFERENCE_ORDERS, len(X)), replace=False)
    STATE["ref"], STATE["ref_y"] = X[idx].copy(), y[idx].copy()
    STATE["region_codes"] = [str(c) for c in STATE["le_map"]["Order Region"].classes_]

    # Sanity check: the wired model must reproduce the labels of real orders.
    p = _calibrated(STATE["model"].predict_proba(STATE["ref"])[:, 1])
    acc = float(((p >= STATE["threshold"]).astype(int) == STATE["ref_y"]).mean())
    print("Model wiring check: %.1f%% agreement with real labels on %d reference orders."
          % (acc * 100, len(idx)))
    if acc < 0.80:
        print("WARNING: agreement is unexpectedly low - check that the assets belong together.")


def startup_pipeline():
    frozen_path    = ASSETS_DIR / "supplyshield_frozen.pkl"
    processed_path = ASSETS_DIR / "processed_data.pkl"

    if frozen_path.exists() and processed_path.exists():
        # Assets already built on this machine (e.g. a previous run) - just load them.
        load_model()
        load_processed()
    else:
        # First run on this machine: no ./assets folder yet. Train once from
        # the raw CSV that must sit next to this file, then freeze the
        # results to ./assets so every later start-up is instant.
        print("=" * 70)
        print("No trained assets found in ./assets - training on this machine now.")
        print("This runs once. It needs the raw CSV (DataCoSupplyChainDataset.csv")
        print("or data.csv) in the same folder as this script, and takes a few")
        print("minutes (XGBoost hyper-parameter search over 180k+ rows).")
        print("=" * 70)
        bundle, processed = train_xgboost()
        save_model(bundle)
        save_processed(processed)
        load_model()
        load_processed()
        print("Training complete - assets/ now holds the trained model.")
        print("Future runs on this machine will start instantly from ./assets.")

    verify_encoders()
    print("Server ready.")


# ─────────────────────────────────────────────────────────────────────────────
#   7. OPTIONAL TRAINING BLOCK (never runs while a frozen model exists)
# ─────────────────────────────────────────────────────────────────────────────


class ESXGB(BaseEstimator, ClassifierMixin):
    """XGBoost wrapper that early-stops inside every CV fold so tuning is fast."""
    def __init__(self, n_estimators=900, max_depth=12, learning_rate=0.03,
                 min_child_weight=3, subsample=0.9, colsample_bytree=0.6,
                 gamma=0.0, reg_alpha=0.0, reg_lambda=1.0, scale_pos_weight=1.0,
                 es_rounds=30):
        self.n_estimators = n_estimators
        self.max_depth = max_depth
        self.learning_rate = learning_rate
        self.min_child_weight = min_child_weight
        self.subsample = subsample
        self.colsample_bytree = colsample_bytree
        self.gamma = gamma
        self.reg_alpha = reg_alpha
        self.reg_lambda = reg_lambda
        self.scale_pos_weight = scale_pos_weight
        self.es_rounds = es_rounds

    def fit(self, X, y):
        Xt, Xe, yt, ye = train_test_split(X, y, test_size=0.08, stratify=y,
                                          random_state=7)
        self.clf_ = XGBClassifier(n_estimators=int(self.n_estimators),
                                  max_depth=int(self.max_depth),
                                  learning_rate=float(self.learning_rate),
                                  min_child_weight=int(self.min_child_weight),
                                  subsample=float(self.subsample),
                                  colsample_bytree=float(self.colsample_bytree),
                                  gamma=float(self.gamma), reg_alpha=float(self.reg_alpha),
                                  reg_lambda=float(self.reg_lambda),
                                  scale_pos_weight=float(self.scale_pos_weight),
                                  tree_method="hist", eval_metric="logloss",
                                  early_stopping_rounds=self.es_rounds, verbose=False,
                                  random_state=42, n_jobs=2)
        self.clf_.fit(Xt, yt, eval_set=[(Xe, ye)], verbose=False)
        return self

    def predict_proba(self, X):
        return self.clf_.predict_proba(X)


def train_models(p):
    X_train, y_train = p["X_train"], p["y_train"]
    X_test,  y_test  = p["X_test"],  p["y_test"]
    final_cols = p["final_cols"]

    def _score(y_true, prob, threshold=0.5):
        y_pred = (np.asarray(prob) >= threshold).astype(int)
        return {
            "Accuracy":  round(accuracy_score(y_true, y_pred) * 100, 2),
            "Precision": round(precision_score(y_true, y_pred, zero_division=0) * 100, 2),
            "Recall":    round(recall_score(y_true, y_pred, zero_division=0) * 100, 2),
            "F1 Score":  round(f1_score(y_true, y_pred, zero_division=0) * 100, 2),
            "ROC-AUC":   round(roc_auc_score(y_true, prob) * 100, 2),
        }

    # Baselines (default 0.5 threshold; LR on scaled features for convergence).
    models = {
        "Logistic Regression": make_pipeline(
            StandardScaler(),
            LogisticRegression(max_iter=2000, n_jobs=-1, random_state=42)),
        "Decision Tree":       DecisionTreeClassifier(max_depth=12, random_state=42),
        "Random Forest":       RandomForestClassifier(n_estimators=120, max_depth=14,
                                                      n_jobs=-1, random_state=42),
    }
    results, trained = {}, {}
    for name, model in models.items():
        model.fit(X_train, y_train)
        trained[name] = model
        results[name] = _score(y_test, model.predict_proba(X_test)[:, 1], 0.5)

    pos_w = float((y_train == 0).sum()) / float((y_train == 1).sum())
    X_tr, X_val, y_tr, y_val = train_test_split(
        X_train, y_train, test_size=0.2, stratify=y_train, random_state=42
    )

    # ── XGBoost tuning: RandomizedSearchCV — 50 combos x 3-fold CV, scoring
    #    ROC-AUC, with early stopping inside every fold (efficient; each fit
    #    is bounded by early_stopping_rounds on a sub-split) ──
    print("Tuning XGBoost: 50 combos x 3-fold CV (early-stopped, roc_auc) ...")
    param_grid = {
        "n_estimators":     [500, 900, 1400],
        "max_depth":        [10, 11, 12, 13, 14],
        "learning_rate":    [0.02, 0.025, 0.03, 0.04, 0.05],
        "min_child_weight": [1, 2, 3, 5],
        "subsample":        [0.8, 0.9, 1.0],
        "colsample_bytree": [0.5, 0.6, 0.7],
        "gamma":            [0.0, 0.1, 0.2],
        "reg_alpha":        [0.0, 0.5, 1.0],
        "reg_lambda":       [1.0, 2.0, 3.0],
    }
    rs = RandomizedSearchCV(ESXGB(scale_pos_weight=pos_w), param_grid, n_iter=50,
                            cv=3, scoring="roc_auc", refit=False, n_jobs=8,
                            random_state=42)
    rs.fit(X_tr, y_tr)
    print("Best CV XGB params:", json.dumps(rs.best_params_))

    # Candidate trio: search winner (tree cap extended) + two validated
    # configurations; the better on the untouched hold-out becomes the model.
    elite = {"max_depth": 14, "learning_rate": 0.025, "subsample": 0.9,
             "colsample_bytree": 0.5, "min_child_weight": 3, "gamma": 0,
             "reg_alpha": 0.0, "reg_lambda": 1.0}
    bpar = dict(rs.best_params_)
    base_n = int(bpar.pop("n_estimators", 900))
    final, pick_auc = None, -1.0
    for cname, cpar, ccap in [("search best", bpar, base_n + 600),
                              ("offline best d14", OFFLINE_WINNER, 1400),
                              ("elite d14", elite, 2800)]:
        c = XGBClassifier(random_state=42, n_jobs=4, eval_metric="auc",
                          tree_method="hist", verbosity=0,
                          scale_pos_weight=pos_w, **cpar, n_estimators=ccap,
                          early_stopping_rounds=60)
        c.fit(X_tr, y_tr, eval_set=[(X_val, y_val)], verbose=False)
        va = float(roc_auc_score(y_val, c.predict_proba(X_val)[:, 1]))
        print("Candidate", cname, cpar, "n=", ccap, "valAUC", round(va, 4))
        if va > pick_auc:
            pick_auc, final = va, c
    print("Selected XGB candidate, hold-out AUC {:.4f}".format(pick_auc))

    # ── Probability calibration (kept only if it improves hold-out AUC) ──
    raw_val = final.predict_proba(X_val)[:, 1]
    cal = IsotonicRegression(out_of_bounds="clip").fit(raw_val, y_val)
    cal_val = cal.predict(raw_val)
    use_cal = roc_auc_score(y_val, cal_val) >= roc_auc_score(y_val, raw_val)

    # ── Operating threshold: best F1 on hold-out with Precision >= 0.78 ──
    op_val = cal_val if use_cal else raw_val
    best_t, best_f1v, best_pr = 0.5, -1.0, 0.0
    for t in np.arange(0.30, 0.80, 0.01):
        pr = precision_score(y_val, op_val >= t, zero_division=0)
        if pr < 0.78:
            continue
        f = f1_score(y_val, op_val >= t, zero_division=0)
        if f > best_f1v + 1e-9:
            best_t, best_f1v, best_pr = float(t), f, float(pr)
    print("Calibration used:", use_cal,
          "| threshold:", round(best_t, 2),
          "| val F1:", round(best_f1v, 3),
          "| val Precision:", round(best_pr, 3))

    raw_te = final.predict_proba(X_test)[:, 1]
    op_te = cal.predict(raw_te) if use_cal else raw_te
    results["XGBoost"] = _score(y_test, op_te, best_t)
    trained["XGBoost"] = final
    xr = results["XGBoost"]
    print("Previous production | Acc 80.58 F1 82.75 AUC 89.29")
    print("New production      | Acc %.2f F1 %.2f AUC %.2f (threshold %.2f)"
          % (xr["Accuracy"], xr["F1 Score"], xr["ROC-AUC"], best_t))

    imps = final.feature_importances_
    imps = imps / (imps.sum() + 1e-12)
    feat_imp = sorted(
        zip(final_cols, imps.tolist()),
        key=lambda x: x[1], reverse=True
    )[:15]

    full_raw = final.predict_proba(p["X_all"])[:, 1]
    full_op = cal.predict(full_raw) if use_cal else full_raw
    low    = int(np.sum(full_op < 0.33))
    medium = int(np.sum((full_op >= 0.33) & (full_op < 0.66)))
    high   = int(np.sum(full_op >= 0.66))

    return (trained, results, feat_imp,
            {"Low": low, "Medium": medium, "High": high},
            final_cols, (cal if use_cal else None), best_t)


def train_xgboost():
    # End-to-end training, run automatically the first time the app starts
    # with no ./assets folder. load_and_preprocess() -> train_models() ->
    # (frozen model bundle, processed-data bundle) -> both written to ./assets
    # by startup_pipeline() so every later start-up loads them instantly
    # instead of retraining.
    p = load_and_preprocess()
    trained, results, feat_imp, risk_dist, final_cols, cal, best_t = train_models(p)
    bundle = {
        "model": trained["XGBoost"],
        "calibrator": cal,
        "threshold": best_t,
        "results": results,
        "feat_imp": feat_imp,
        "risk_dist": risk_dist,
        "final_cols": final_cols,
        "le_map": p["le_map"], "te_map": p["te_map"], "gmean": p["gmean"],
        "numeric_cols": p["numeric_cols"], "label_cols": p["label_cols"],
        "te_cols": p["te_cols"], "te_interact": p["te_interact"],
        "freq_maps": p["freq_maps"],
        "defaults_num": p["defaults_num"], "defaults_cat": p["defaults_cat"],
        "y_all": p["y_all"],
    }
    return bundle, p




